package strfmt

import "strings"

// BUG: repeats the last character instead of the first
func Repeat(s string, n int) string {
	if s == "" || n <= 0 {
		return ""
	}
	return strings.Repeat(string(s[len(s)-1]), n)
}

// BUG: truncates from the beginning instead of the end
func Truncate(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[len(s)-maxLen:]
}

// BUG: pads on the left instead of the right
func PadRight(s string, width int, pad rune) string {
	if len(s) >= width {
		return s
	}
	return strings.Repeat(string(pad), width-len(s)) + s
}

package strfmt

import "testing"

func TestRepeat(t *testing.T) {
	if got := Repeat("abc", 3); got != "aaa" {
		t.Fatalf("want aaa, got %q", got)
	}
}

func TestTruncate(t *testing.T) {
	if got := Truncate("hello world", 5); got != "hello" {
		t.Fatalf("want hello, got %q", got)
	}
}

func TestPadRight(t *testing.T) {
	if got := PadRight("hi", 5, '-'); got != "hi---" {
		t.Fatalf("want hi---, got %q", got)
	}
}

func TestRepeatEmpty(t *testing.T) {
	if got := Repeat("", 3); got != "" {
		t.Fatalf("want empty, got %q", got)
	}
}

func TestTruncateShort(t *testing.T) {
	if got := Truncate("hi", 10); got != "hi" {
		t.Fatalf("want hi, got %q", got)
	}
}
